'use strict';

const SECURITY_HEADERS = Object.freeze({
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'no-referrer',
});

function applySecurityHeaders(res) {
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    res.setHeader(name, value);
  }
  return res;
}

function sendJson(res, statusCode, payload) {
  const body = JSON.stringify(payload);
  applySecurityHeaders(res);
  res.statusCode = statusCode;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Content-Length', Buffer.byteLength(body, 'utf8'));
  res.end(body);
}

function sendNotFound(res) {
  sendJson(res, 404, { error: 'not_found' });
}

module.exports = { SECURITY_HEADERS, applySecurityHeaders, sendJson, sendNotFound };
```

Careful: tests assert exact body; JSON.stringify gives `{"status":"ok"}`. Content-Length fine.

src/server.js:
```js
'use strict';

const http = require('node:http');
const { sendJson, sendNotFound } = require('./http');

const DEFAULT_PORT = 3000;

function resolvePort(env = process.env) {
  const raw = env.PORT;
  if (raw === undefined || raw === null || String(raw).trim() === '') {
    return DEFAULT_PORT;
  }
  const trimmed = String(raw).trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error(`PORT 必须是 1-65535 的整数，实际为 "${raw}"`);
  }
  const port = Number(trimmed);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`PORT 必须是 1-65535 的整数，实际为 "${raw}"`);
  }
  return port;
}

function handler(req, res) {
  const url = req.url || '/';
  const pathname = url.split('?')[0];
  if (req.method === 'GET' && pathname === '/health') {
    sendJson(res, 200, { status: 'ok' });
    return;
  }
  sendNotFound(res);
}

function createServer() {
  return http.createServer(handler);
}

function start() {
  let port;
  try {
    port = resolvePort(process.env);
  } catch (err) {
    console.error(err.message);
    process.exitCode = 1;
    return;
  }
  const server = createServer();
  server.on('error', (err) => {
    console.error(`服务启动失败：${err.message}`);
    process.exit(1);
  });
  server.listen(port, () => {
    console.log(`HTTP 服务已启动，监听端口 ${server.address().port}`);
  });
  return server;
}

if (require.main === module) {
  start();
}

module.exports = { DEFAULT_PORT, resolvePort, createServer, handler, start };
```

